import{prepareS1Continuous}from'../hacheong-brackish/s1-continuous.mjs';
import{prepareS1SharedImage}from'../s1-local/shared-image.mjs';
import{prepareS1Local}from'../s1-local/presentation.mjs';
import{prepareBrackishRegion}from'../hacheong-brackish/provider.mjs';
import{composeS1JourneySupport}from'./compose-support.mjs';
// Fixed new presentation factory; old prepareS1Continuous API/geometry unchanged.
export async function prepareS1StageExitContinuous({signal,...options}={}){
 let old,local,east,shared,closed=false,active=null;
 const dispose=()=>{if(closed)return;closed=true;let first;for(const p of[old,local,east,shared])try{p?.dispose()}catch(e){first??=e}old=local=east=shared=null;if(first)throw first};
 try{old=await prepareS1Continuous({signal,presentation:false,...options});shared=await prepareS1SharedImage({signal,...options});const imageOptions={sharedImageToken:shared.token};local=await prepareS1Local({signal,...options,...imageOptions});east=await prepareBrackishRegion('eastRoad',{signal,...options,...imageOptions});shared.dispose();shared=null;if(signal?.aborted)throw Error('S1_STAGE_EXIT_ABORTED');
 const extra={safe:east.safe,validate:n=>east.validate(n)===true,describe(f,facing){if(!east.safe(f)||!['up','down','left','right'].includes(facing))throw Error('S1_EAST_ROAD_POSE');const R=east.pins;return{sceneId:R.sceneId,mapId:R.mapId,revision:R.revision,imageSHA:R.imageSHA,maskSHA:R.maskSHA,foot:[...f],facing}},supportPinsVerified:true};const merged=composeS1JourneySupport(old,extra),provider=f=>f[0]<=1776?local:east,check=()=>{if(closed||signal?.aborted)throw Error('S1_STAGE_EXIT_CLOSED')};
 return Object.freeze({get supportPinsVerified(){return!closed&&merged.supportPinsVerified},get imageBytesVerified(){return!closed},safe:f=>!closed&&merged.safe(f),describe:(...args)=>{check();return merged.describe(...args)},validate:n=>!closed&&merged.validate(n),noteStep(from,to){check();if(!merged.safe(from)||!merged.safe(to)||Math.abs(from[0]-to[0])+Math.abs(from[1]-to[1])!==1)throw Error('S1_STAGE_EXIT_CARDINAL');if((from[0]<=1776)!==(to[0]<=1776)&&(!(from[1]>=984&&from[1]<=1047)||from[1]!==to[1]))throw Error('S1_STAGE_EXIT_OLD_SEAM');active=provider(to);active.resetCameraForSceneOrRestore(to)},draw(ctx,options){check();if(!merged.safe(options.foot))throw Error('S1_STAGE_EXIT_UNSAFE');const p=provider(options.foot);if(p!==active){p.resetCameraForSceneOrRestore(options.foot);active=p}if(p===east){const prior=p.getFoot();if(prior[0]!==options.foot[0]||prior[1]!==options.foot[1]){const dx=options.foot[0]-prior[0],dy=options.foot[1]-prior[1];if(dx&&dy)throw Error('S1_STAGE_EXIT_DRAW_PATH');let f=[...prior];for(let i=0;i<Math.abs(dx)+Math.abs(dy);i++){f=[f[0]+Math.sign(dx),f[1]+Math.sign(dy)];p.trackFoot(f)}}}return p.draw(ctx,options)},resetCameraForSceneOrRestore(f){check();if(!merged.safe(f))throw Error('S1_STAGE_EXIT_UNSAFE');active=provider(f);return active.resetCameraForSceneOrRestore(f)},dispose});
 }catch(e){try{dispose()}catch{}throw e}
}
